const DICT: Record<Locale, Record<QKey, string>> = { uz, ru, en };

export function useQt() {
  const locale = useUI((s) => s.locale);
  return useCallback(
    (key: QKey, vars?: Record<string, string | number>) => {
      let text = DICT[locale]?.[key] ?? uz[key] ?? key;
      if (vars) for (const [k, v] of Object.entries(vars)) text = text.replaceAll(`{${k}}`, String(v));
      return text;
    },
    [locale],
  );
}

export type QT = ReturnType<typeof useQt>;

/** Xato turi bo'yicha tanlangan tildagi sarlavha va tavsiya (backend matni zaxira). */
export function errorText(t: QT, err: { kind: string; title: string; hint: string } | null | undefined) {
  if (!err) return null;
  const key = `err_${err.kind}` as QKey;
  const hintKey = `err_${err.kind}_hint` as QKey;
  return { title: key in uz ? t(key) : err.title, hint: hintKey in uz ? t(hintKey) : err.hint };
}
